public class Student {
    String name;
    int age;

    Student(String name, int age) {
        this.name = name;     // 'this.name' is the field, 'name' is the parameter
        this.age = age;
    }

    Student(String name) {
        this(name, 18);        // constructor chaining — delegates to the other constructor
    }

    public static void main(String[] args) {
        Student s1 = new Student("Asha", 21);
        Student s2 = new Student("Ravi");     // uses the default age of 18
        System.out.println(s1.name + " " + s1.age + ", " + s2.name + " " + s2.age);
    }
}
